export async function imageResult(file_path: string, mimeType: "image/png" | "image/jpeg", note?: string): Promise<CallToolResult> {
  const text = { type: "text" as const, text: note === undefined ? file_path : `${note}
${file_path}` };
  if (previewMode === "path") return { content: [text] };
  const data = (await readFile(file_path)).toString("base64");
  const image = { type: "image" as const, data, mimeType };
  return { content: previewMode === "inline" ? [image] : [image, text] };
}
